type Captured = { path: string; method?: string; body: unknown; headers: IncomingHttpHeaders }
type Reply = { status?: number; body?: unknown; action?: 'drop' | 'hold' | 'headers-only' }

export async function startInvitationFixture() {
  const captured: Captured[] = []
  const replies: Record<string, Reply> = {}
  const sockets = new Set<Socket>()
  const held = new Set<ServerResponse>()
  const heldByPath = new Map<string, ServerResponse>()
  const waiters: Array<{ path: string; resolve: () => void }> = []
  const server = createServer(async (request, response) => {
    let raw = ''
    for await (const part of request) raw += part.toString()
    const path = request.url || ''
    captured.push({ path, method: request.method, headers: request.headers, body: raw ? JSON.parse(raw) : null })
    const reply = replies[path] || {
      body: path === '/auth/v1/user' ? providerUser : path === '/rest/v1/rpc/status' ? [pendingRow] : [acceptedRow],
    }
    if (reply.action === 'drop') request.socket.destroy()
    else if (reply.action === 'hold' || reply.action === 'headers-only') {
      held.add(response)
      heldByPath.set(path, response)
      response.once('close', () => { held.delete(response); heldByPath.delete(path) })
      if (reply.action === 'headers-only') {
        response.writeHead(reply.status || 200, { 'Content-Type': 'application/json', 'X-Supabase-Api-Version': '2024-01-01' })
        response.write('[')
      }
    } else {
      response.writeHead(reply.status || 200, { 'Content-Type': 'application/json', 'X-Supabase-Api-Version': '2024-01-01' })
      response.end(JSON.stringify(reply.body))
    }
    for (const waiter of waiters.filter(item => item.path === path)) waiter.resolve()
  })
  server.on('connection', socket => {
    sockets.add(socket)
    socket.once('close', () => sockets.delete(socket))
  })
  await new Promise<void>(resolve => server.listen(0, '127.0.0.1', resolve))
  const address = server.address()
  if (!address || typeof address === 'string') throw new Error('Loopback fixture unavailable')
  return {
    url: `http://127.0.0.1:${address.port}`, captured, replies,
    waitFor(path: string) {
      return captured.some(item => item.path === path) ? Promise.resolve() : new Promise<void>(resolve => waiters.push({ path, resolve }))
    },
    release(path: string, body: unknown) {
      const response = heldByPath.get(path)
      if (!response) throw new Error('No held fixture response')
      response.writeHead(200, { 'Content-Type': 'application/json', 'X-Supabase-Api-Version': '2024-01-01' })
      response.end(JSON.stringify(body))
    },
    async close() {
      const closed = [...sockets].map(socket => new Promise<void>(resolve => socket.once('close', () => resolve())))
      for (const response of held) response.destroy()
      for (const socket of sockets) socket.destroy()
      await new Promise<void>((resolve, reject) => server.close(error => error ? reject(error) : resolve()))
      await Promise.all(closed)
      return { listening: server.listening, sockets: sockets.size, held: held.size }
    },
  }
}
